-- 158_replace_decision_70_2026_takaful_insurance_companies_rules_polluted_with_watermark_page_headers_duplicated_blob_and_merged_articles_with_preamble_and_22_articles.sql
--
-- إعادة رفع قرار مجلس إدارة الهيئة العامة للرقابة المالية رقم (70) لسنة 2026 بشأن قواعد ومعايير وضوابط تنظيم عمل الشركات المرخص لها بمزاولة التأمين التكافلي فى مصر،
-- المنشور بالوقائع المصرية، العدد 100 (تابع - أ)، فى 6 مايو 2026 (الصفحات 3 إلى 17).
--
-- ===== الحالة السابقة (مراجعة الـ153 وثيقة، أولوية P2 - المجموعة د) =====
-- مخزَّن بالهجرات 004 و005 و006 (20 صفاً، 30570 حرفاً) مأخوذ من طبقة النص فى PDF دون تنظيف، وبهيكل غير سليم: الهجرتان 004 و005 تدخلان 10 صفوف فقط، منها الصف 10 (9822 حرفاً) يحوى نص المواد 10 إلى 22 كلها فى صف واحد
-- بما فيها عناوين المواد 11-22 ("المادة الحادية عشرة (" ... "المادة الثانية والعشرون ("). ثم تضيف 006 (الإدراج ON CONFLICT DO NOTHING) الصفوف 11-20 فتتكرر المواد 11-19 مرتين (فى الصف 10 وفى صفوفها)، ويضم الصف 20 المواد 20 و21 و22 معاً مع التوقيع،
-- فلا وجود للمادتين 21 (إلغاء القرار 23 لسنة 2019) و22 (النشر والعمل) كصفين مستقلين.
-- وقورن المخزَّن بالنص المنقول من المصدر كلمة بكلمة بعد توحيد الهمزات والياء والتاء المربوطة وحذف التشكيل وعلامات الترقيم، فلم يبق فرق فى ألفاظ القرار نفسه إلا ما يأتى، وكله تلوث من الاستخراج:
-- (1) شظايا نص العلامة المائية القطرية للوقائع ("صورة إ" و"لك" و"تروني" و"ة ال يع" و"تد بها" و"عند ا" و"ل" و"تداول") فى 18 صفاً من 20 تتخلل الجمل وتقطعها؛ (2) ترويسة صفحات الوقائع
-- ("الوقائع المصریة - العدد 100 تابع (أ) فى 6 مايو سنة 2026" ورقم الصفحة) فى 15 صفاً؛ (3) عناوين المواد داخل المتن بدل أن تكون حقل عنوان مستقل (وفى الصف 1 تتوسط الكلمتان "ل" و"تداول" سطر عنوان المادة)؛
-- (4) المادة 4 ثالثاً البند 1 ("تدير شركة التأمين التكافلي إدارة أعمال التأمين بصفتها وكيلاً عن المشتركين") والمادة 6 البند 2 (".. أو أي شركة تأمين أخرى تزاول ذات النشاط أو عضواً بمجلس إدارة أي من الشركات السابقة") مبعثرتا الأسطر
-- ومقطوعتا الكلمات ("يلا / صفتها وك / أمين ب ..." و"س / ضو ا بمجل / شاط أو ع / زاول ذات الن ..." تتخللهما شظايا العلامة المائية)؛ (5) المادة 7 البند 9: أرقام الإحالة "(1 ، 2)" مقلوبة الأقواس والترتيب؛
-- (6) حروف خاصة من الخط (U+E821 وU+E823) فى 9 صفوف (2 و4 و5 و6 و7 و10 و11 و13 و20) محل الضمة والتنوين فى كلمات مثل "ي ُستحق" و"مضارب ًا" و"بناءً"، وتنوين مفصول عن حرفه ("وفق ًا" و"تنفيذ ًا" و"طب ًقا")، وأرقام هندية وفارسية فى 17 صفاً،
-- وأرقام البنود والنسب (50% و30% ...) ملتصقة بالكلمة التالية؛ (7) بلا ديباجة (الاطلاعات والعرض على لجنة الرقابة الشرعية المركزية وموافقة مجلس الإدارة بجلسة 2026/3/18) ولا عنوان للقرار.
-- فلا يصلح النص المخزَّن للاستشهاد الرسمى، ولا لإدخاله إلى سياق نموذج اللغة: شظايا العلامة المائية والترويسة تقطع الجمل، والمتن مكرر فى صفين، والمادتان 21 و22 بلا صف مستقل.
--
-- ===== المصدر والمنهجية =====
-- PDF الوقائع المصرية (15 صفحة، 574.8 كيلوبايت) قدّمه صاحب المشروع. فى الملف طبقة نصية بخط مضمَّن، تتخللها كتل العلامة المائية القطرية بخط مستقل (AhabHeadline)، فنُزعت من الملف أوامر عرض هذا الخط وحده (دون مساس بباقى المحتوى) ثم
-- استُخرج النص بترتيبه المنطقى وحُوِّلت الصيغ الشكلية للحروف إلى حروف عادية (NFKC)، وأعيد تركيب الفقرات من أسطر الصفحة بإحداثيات الأسطر (بداية الفقرة سطر مُزاح عن الهامش الأيمن) لا بالتخمين، وصُحِّح ما يفسده تخزين الأحرف بترتيب بصرى:
-- معكوسات الأقواس، وترتيب أرقام الإحالة داخل الأقواس (البندان "1 ، 2" بالمادة 7/9، تحققت منه بإحداثيات الحروف فى الصفحة)، والنسب المئوية، وسطرا المادتين 4 و6 المبعثران (رُتبت أجزاؤهما بإحداثيات الأسطر وقُرئتا بصرياً).
-- ثم قوبل النص المُدخَل بمخرجات OCR مستقلة (tesseract ara) على صور الصفحات بعد إزالة خلفية العلامة المائية: لم يبق فرق فى ألفاظ غير ضجيج التعرف على الحروف والأرقام الهندية والعناوين ولا فرق حقيقى فى كلمة واحدة، وقُرئت بصرياً المواضع المشتبهة (الأقواس والنسب المئوية
-- ومعادلات المادة 14 وتنوين "مضاربًا" و"ثانيًا" و"طبقًا" والتوقيع). أُبقيت كتابة الوقائع كما طُبعت ("أحكم الشريعة الإسلامية" بالديباجة، "الرصيد القرض" والمشاركين بدل المشتركين بالمادة 15، "فى" و"في" معاً، "إتباع" و"إثنين"، "تري" بالمادة 12،
-- و"لما يرد" بالمادة 20)؛ الأرقام لاتينية والتنوين فى موضعه كما طُبع (وفقًا، تنفيذًا، مضاربًا، بناءً، وكيلاً) وأُسقطت الضمة وغيرها من علامات التشكيل الصغيرة؛ ضُبطت المسافات حول الفاصلة والنقطتين والفاصلة المنقوطة (" ، " و" : " و" ؛ ")
-- وحول علامة الجمع، وأُضيفت مسافة بين الرقم أو القوس والكلمة الملتصقة به؛ وأُبقيت النقطة الأخيرة كما طُبعت. النسب المئوية بلا مسافات داخل الأقواس "(50%)" (المسافات الداخلية فى الطباعة تباعد أسطر لا حروف). حُذفت الترويسة وأرقام الصفحات وشعار العلامة المائية،
-- وسطر "مجلس إدارة الهيئة العامة للرقابة المالية" (جهة الإصدار)، وعنوان القرار يوضع فى hierarchical_location للديباجة. التوقيع ("رئيس مجلس إدارة / الهيئة العامة للرقابة المالية / د/ إسلام عبد العظيم عزام") داخل المادة 22.
--
-- ===== الهيكل =====
-- 23 صفاً، 23 نسخة (version_no = 1): ديباجة (article_no = 0) بالاطلاعات الخمسة (القانون 10 لسنة 2009، قانون التأمين الموحد 155 لسنة 2024، القرارات 23 لسنة 2019 و42 لسنة 2019 و15 لسنة 2025) والعرض على لجنة الرقابة الشرعية المركزية
-- وموافقة مجلس الإدارة بتاريخ 2026/3/18، ثم المواد 1 إلى 22 بأرقامها الأصلية وعناوينها (حقل title) (المواد 20-22 بلا عنوان كما فى الأصل)؛ لا فصول فى القرار فلا hierarchical_location للمواد. أُبقيت المواد بمفاتيحها (1..22، 0) حتى لا تعيد بذور 004/005/006
-- إدراج المواد القديمة (إدراج laws فيها ON CONFLICT DO NOTHING، وإدراج المواد مبنى على RETURNING فلا يعمل مع قانون موجود).
--
-- ===== التاريخ =====
-- effective_from = 2026-05-07: المادة 22 تعمل بالقرار "من اليوم التالي لتاريخ نشره"، ونشره بالعدد 100 (تابع - أ) بتاريخ 2026/5/6 (ثابت بترويسة كل صفحة). كان القديم تاريخ تشغيل البذر لا تاريخ سريان. لا تُمس بيانات laws.
-- (المادة 21 تلغى قرار الهيئة 23 لسنة 2019؛ حالة ذلك القرار فى laws خارج نطاق هذه الهجرة.)
--
-- ===== قابلية إعادة التشغيل =====
-- الحذف مشروط بألا تكون الحالة نظيفة (23 صفاً بديباجة سليمة والمادة 22 موجودة)؛ والإدراج ON CONFLICT DO NOTHING. تحقق الختام محصور فى هذا القرار ويفشل عند أى انحراف (عدد، علامة مائية أو ترويسة متبقية، أو تلف، أو محتوى المواد،
-- أو إجمالى الطول 19752 حرفاً).
--
-- ملاحظة تشغيلية: المواد الجديدة بلا embedding؛ يلزم scripts/backfill-embeddings.js بعد النشر.

BEGIN;
DO $fix158$
DECLARE
  v_law_id uuid;
  v_n int;
BEGIN
  SELECT id INTO v_law_id FROM laws WHERE law_no = 70 AND law_year = 2026 AND kind = 'board_decision';
  IF v_law_id IS NULL THEN
    RAISE WARNING '[158] القرار 70/2026 غير موجود فى laws — تخطّى';
    RETURN;
  END IF;
  IF (SELECT count(*) FROM articles WHERE law_id = v_law_id) = 23
     AND EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 0 AND article_suffix_order = 0 AND title = 'ديباجة القرار' AND body LIKE 'بعد الاطلاع%')
     AND EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 22 AND article_suffix_order = 0) THEN
    RAISE NOTICE '[158] القرار 70/2026 نظيف بالفعل — تخطّى الحذف';
  ELSE
    SELECT count(*) INTO v_n FROM articles WHERE law_id = v_law_id;
    DELETE FROM articles WHERE law_id = v_law_id;
    RAISE NOTICE '[158] أُزيلت % مادة من القرار 70/2026 (نص مخزَّن ملوَّث بعلامة مائية وترويسات صفحات وعناوين مواد، ومتن واحد مكرر، ودمج المواد 20-22)', v_n;
  END IF;
END
$fix158$;

WITH ins0_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 0, 0, $h0$قرار مجلس إدارة الهيئة العامة للرقابة المالية رقم 70 لسنة 2026 (منشور بالوقائع المصرية العدد 100 تابع (أ) فى 2026/5/6) بشأن قواعد ومعايير وضوابط تنظيم عمل الشركات المرخص لها بمزاولة التأمين التكافلي فى مصر$h0$, $t0_0$ديباجة القرار$t0_0$, $b0_0$بعد الاطلاع على القانون رقم 10 لسنة 2009 بتنظيم الرقابة على الأسواق والأدوات المالية غير المصرفية ؛
وعلى قانون التأمين الموحد الصادر بالقانون رقم 155 لسنة 2024 والقرارات الصادرة تنفيذًا له ؛
وعلى قرار مجلس إدارة الهيئة رقم 23 لسنة 2019 بشأن إصدار ضوابط لتنظيم التأمين التكافلي للعمل بها في سوق التأمين المصري ؛
وعلى قرار مجلس إدارة الهيئة رقم 42 لسنة 2019 بشأن ضوابط تشكيل واشتراطات عضوية لجان الرقابة الشرعية لإصدارات الصكوك والمنتجات المالية غير المصرفية المتوافقة مع أحكم الشريعة الإسلامية ؛
وعلى قرار مجلس إدارة الهيئة رقم 15 لسنة 2025 بشأن قواعد التأسيس والترخيص للشركات العاملة في نشاط التأمين أو إعادة التأمين ؛
وبعد العرض على لجنة الرقابة الشرعية المركزية ؛
وبعد موافقة مجلس إدارة الهيئة بجلسته المنعقدة بتاريخ 2026/3/18 ؛$b0_0$
  FROM laws WHERE law_no = 70 AND law_year = 2026 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2026-05-07', 'active' FROM ins0_0;

WITH ins1_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 1, 0, NULL, $t1_0$المادة الأولى - نطاق التطبيق$t1_0$, $b1_0$تسري أحكام هذا القرار في شأن قواعد ومعايير وضوابط تنظيم عمل الشركات المرخص لها بمزاولة التأمين التكافلي في مصر .$b1_0$
  FROM laws WHERE law_no = 70 AND law_year = 2026 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2026-05-07', 'active' FROM ins1_0;

WITH ins2_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 2, 0, NULL, $t2_0$المادة الثانية - التعريفات$t2_0$, $b2_0$في تطبيق أحكام هذا القرار ، يقصد بالكلمات والعبارات الآتية المعنى المبين قرين كل منها :
شركة التأمين التكافلي : هي الشركة المرخص لها من الهيئة بمزاولة أعمال التأمين التكافلي وفقًا لأحكام ومبادئ الشريعة الإسلامية في كافة معاملاتها بما في ذلك أنشطتها التأمينية والاستثمارية ، وتقوم بإدارة عمليات التأمين التكافلي واستثمار أموال المشتركين في مقابل أجر معلوم باعتبارها وكيلاً أو حصة معلومة باعتبارها مضاربًا أو كليهما وذلك بما يتفق مع أحكام ومبادئ الشريعة الإسلامية ، وتلتزم ببذل العناية اللازمة للمحافظة على الملاءة المالية لصندوق المشتركين الذي تديره .
المشترك : هو الشخص الذي يتعاقد مع شركة التأمين التكافلي من خلال إبرام وثيقة تأمين معها ، ويلتزم بدفع الاشتراك لها ويحق له أو لورثته الشرعيين أو المستفيدين بحسب الأحوال الحصول على التعويض أو المنافع التي تقدمها الشركة .
حساب التكافل (صندوق المشتركين) : هو الحساب الذي تنشئه شركة التأمين التكافلي لإيداع مبالغ الاشتراك المحصلة من المشتركين وعوائد استثمارها به والإيرادات الناتجة عن عمليات إعادة التأمين ، ويكون له ذمة مالية مستقلة عن الذمة المالية للشركة ، ويكون هذا الحساب مسئولاً عن تعويض المشتركين والمستفيدين والمتضررين من الغير وفقًا لشروط وثائق التأمين التكافلي ، حيث تدفع منه مبالغ التعويضات وما يتصل بذلك من مخصصات أو احتياطيات حسب ما تحدده الهيئة وأجر إدارة العملية التأمينية والاستثمارية على أساس النموذج المحدد بالنظام الأساسي للشركة والموافق عليه من الهيئة .
الفائض التأميني : هو ما تبقى من صافي أقساط المشتركين وعوائدها والإيرادات الأخرى المتعلقة بوثائق التأمين بعد خصم كافة المصروفات وصافي التعويضات المدفوعة والمخصصات الفنية خلال السنة المالية .$b2_0$
  FROM laws WHERE law_no = 70 AND law_year = 2026 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2026-05-07', 'active' FROM ins2_0;

WITH ins3_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 3, 0, NULL, $t3_0$المادة الثالثة - الترخيص بمزاولة التأمين التكافلي$t3_0$, $b3_0$على الشركات الراغبة في مزاولة التأمين التكافلي الحصول على ترخيص بذلك من الهيئة وفقًا للقواعد المعمول بها في هذا الشأن ، على أن تراعي الشركة في عقد تأسيسها ونظامها الأساسي الأحكام الواردة في هذا القرار ، مع ذكر بيانات الأسماء المرشحة لعضوية لجنة الرقابة الشرعية رفق طلب الحصول على الترخيص .$b3_0$
  FROM laws WHERE law_no = 70 AND law_year = 2026 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2026-05-07', 'active' FROM ins3_0;

WITH ins4_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 4, 0, NULL, $t4_0$المادة الرابعة - إدارة شركة التأمين التكافلي لحساب التكافل (صندوق المشتركين)$t4_0$, $b4_0$تتولى شركة التأمين التكافلي إدارة حساب التكافل وأعمال الاستثمار المرتبطة بالاشتراكات على أساس نموذج الوكالة أو المضاربة أو كليهما معًا ، على أن يتم تحديد الأحكام الخاصة بذلك بالنظام الأساسي للشركة والجزء المخصص للتأمين التكافلي الوارد بوثيقة التأمين ، وذلك بمراعاة الأحكام الآتية :
أولاً - نموذج الوكالة :
1- تدير شركة التأمين التكافلي كل من أعمال التأمين وأنشطة الاستثمار المرتبطة بها بموجب عقد وكالة يعين بمقتضاه المشتركون الشركة لتكون وكيلاً عنهم في إدارة تلك الأعمال واستثمار الأموال الناشئة عنها نيابة عنهم .
2- تتقاضى الشركة أجر من المشتركين في شكل نسبة من الاشتراكات المحصلة منهم يتم تحديدها بالشكل الذي يحقق العدالة وعدم الإضرار بمصالح المشتركين بناءً على الدراسة الفنية والاكتوارية التي يتم إعدادها في هذا الشأن وموافقة الهيئة عليها ، على أن يؤخذ رأي لجنة الرقابة الشرعية في النسبة المشار إليها ، ويجوز بالنسبة لوثائق تأمينات الحياة أن تكون هذه النسبة متغيرة طبقًا لمدة الوثيقة . ويستحق الأجر المشار إليه مقابل قيمة المصروفات العمومية والإدارية لإدارة أعمال المشتركين وهامش ربح المساهمين .
ثانيًا - نموذج المضاربة :
1- تدير شركة التأمين التكافلي كل من أعمال التأمين وأنشطة الاستثمار بصفتها مضاربًا وذلك لصالح المشتركين في نظام التكافل .
2- تستحق الشركة مقابل إدارتها لأعمال التأمين وأنشطة الاستثمار نسبة من الفائض التأميني لا يجاوز (50%) منه ، على أن تحدد هذه النسبة في النظام الأساسي للشركة وكذا في وثيقة التأمين .
ثالثًا - نموذج الوكالة والمضاربة معًا :
1- تدير شركة التأمين التكافلي إدارة أعمال التأمين بصفتها وكيلاً عن المشتركين ، كما تدير أنشطة الاستثمار بصفتها مضاربًا وذلك لصالح المشتركين في نظام التكافل .
2- تستحق الشركة مقابل خدماتها في إدارة أعمال التأمين في شكل نسبة من الاشتراكات المحصلة من المشتركين يتم تحديدها بالشكل الذي يحقق العدالة وعدم الإضرار بمصالح المشتركين بناءً على الدراسة الفنية والاكتوارية التي يتم إعدادها في هذا الشأن وبعد موافقة الهيئة عليها ، ويؤخذ رأي لجنة الرقابة الشرعية في النسبة المشار إليها . ويجوز بالنسبة لوثائق تأمينات الحياة أن تكون هذه النسبة متغيرة طبقًا لطبيعة الوثائق ومددها ، كما تستحق الشركة نسبة من صافي عوائد استثمار أموال المشتركين مقابل إدارة أنشطة الاستثمار على أن تحدد هذه النسبة في النظام الأساسي للشركة والوثيقة بما لا يجاوز (30%) صافي عوائد استثمار أموال المشتركين .$b4_0$
  FROM laws WHERE law_no = 70 AND law_year = 2026 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2026-05-07', 'active' FROM ins4_0;

WITH ins5_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 5, 0, NULL, $t5_0$المادة الخامسة - وثائق التأمين التكافلي$t5_0$, $b5_0$على شركات التأمين التكافلي تضمين وثيقة التأمين جزءًا خاصة بالأحكام المتعلقة بالتأمين التكافلي بشكل واضح وظاهر ، على أن يتضمن الأسس والمبادئ الرئيسية للتأمين التكافلي التي تعتمدها الشركة في علاقتها مع المشتركين بها ، وعلى وجه الأخص ما يلي :
1- الأسس والقواعد التي تحكم العلاقة التكافلية بين الشركة والمشترك بما في ذلك الطبيعة القانونية لتلك العلاقة .
2- توضيح أن ما يدفعه المؤمن له يكون على سبيل الاشتراك (التبرع) .
3- الإفصاح عن التزام الشركة في حالة وجود عجز في حساب التكافل بأن يتم سداد الالتزامات المترتبة على هذا الصندوق وفقًا للضوابط الواردة بهذا القرار .
4- تحديد مقدار أجر الوكالة الذي تستحقه شركة التأمين التكافلي حال إتباعها لنموذج الوكالة ، وحصة الشركة من فائض النشاط التأميني حال إتباعها لنموذج المضاربة ، وحصة الشركة حال إتباعها لنموذجي الوكالة والمضاربة معًا .
5- ملخص عن السياسات الاستثمارية التي تتبعها الشركة في استثمار الأجزاء المخصصة للاستثمار من الاشتراكات على أن تكون متفقة مع أحكام قانون التأمين الموحد والقرارات الصادرة تنفيذًا له وأحكام ومبادئ الشريعة الإسلامية .
6- الإفصاح عن طريقة توزيع الفائض التأميني التي تطبقها الشركة ، وذلك بمراعاة أحكام المادة (194) من قانون التأمين الموحد .
7- الآلية التي ستتبعها الشركة في حال عدم استلام المشتركين للفائض التأميني ، على أن يتم توزيعه في أوجه الخير أو التبرع وبعد موافقة الهيئة .$b5_0$
  FROM laws WHERE law_no = 70 AND law_year = 2026 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2026-05-07', 'active' FROM ins5_0;

WITH ins6_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 6, 0, NULL, $t6_0$المادة السادسة - شروط عضوية لجنة الرقابة الشرعية بالشركة$t6_0$, $b6_0$تلتزم شركة التأمين التكافلي بتشكيل لجنة رقابة شرعية من ثلاثة أعضاء على الأقل ، ويشترط في عضو لجنة الرقابة الشرعية بالشركة ما يلي :
1- أن يكون مقيدًا بالسجل المعد لهذا الغرض بالهيئة .
2- ألا يكون مساهمًا بالشركة أو أي من شركاتها القابضة أو التابعة أو الشقيقة أو أي شركة تأمين أخرى تزاول ذات النشاط أو عضوًا بمجلس إدارة أي من الشركات السابقة .
3- ألا يكون من العاملين بأي من الشركات المشار إليها بالبند السابق .
4- ألا يكون عضوًا في لجنة رقابة شرعية في أكثر من شركتين تأمين تكافلي تزاول ذات النشاط .
5- ألا تكون له مصلحة مباشرة أو غير مباشرة في الأعمال والعقود التي تتم لحساب الشركة ، فيما عدا الأعمال والعقود التي تتم معه بذات الأحكام والشروط التي تتبعها الشركة مع أي متعاقد آخر وتدخل ضمن نشاط الشركة المعتاد .
6- ألا يكون عليه أي التزام مالي تجاه الشركة أو أي من أعضاء مجلس إدارتها أو إدارتها العليا ؛ كالقروض أو أي مديونيات أخرى ، بشكل يمكن أن يؤثر على استقلالية رأيه .$b6_0$
  FROM laws WHERE law_no = 70 AND law_year = 2026 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2026-05-07', 'active' FROM ins6_0;

WITH ins7_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 7, 0, NULL, $t7_0$المادة السابعة - إجراءات تشكيل وانعقاد واتخاذ قرارات لجنة الرقابة الشرعية$t7_0$, $b7_0$تتبع الإجراءات الآتية في شأن تشكيل لجنة الرقابة الشرعية بالشركة وانعقاد اجتماعاتها واتخاذ القرارات بها :
1- يتم ترشيح أعضاء لجنة الرقابة الشرعية من قبل مجلس إدارة شركة التأمين التكافلي بناءً على توصية لجنة الترشيحات والمكافآت بالشركة .
2- يتم عرض أسماء المرشحين ومؤهلاتهم على الهيئة قبل خمسة وأربعين يومًا من تاريخ انعقاد الجمعية العامة العادية للشركة .
3- تقوم الهيئة بفحص طلبات المرشحين والتأكد من استيفاء الشروط المتطلبة في شأنهم ، وللهيئة مخاطبة الشركة أو المرشحين لاستيفاء أي بيانات أو مستندات ترى ضرورة تقديمها للبت في طلب الترشح ، وتقوم الهيئة بإخطار الشركة بأسماء المرشحين الذين تم الموافقة عليهم والمعترض عليهم ، على أن تقوم الشركة بترشيح بديل عن المرشح المعترض عليه .
4- تعرض أسماء المرشحين الذين وافقت عليهم الهيئة على الجمعية العامة للشركة للنظر في الموافقة على تعيينهم كأعضاء للجنة الرقابة الشرعية بالشركة وتحديد أتعابهم ، ويتم إخطار الهيئة خلال مدة لا تجاوز عشرة أيام من تاريخ اجتماع الجمعية العامة بنتيجة ذلك .
5- تكون مدة تعيين لجنة الرقابة بالشركة ثلاث سنوات قابلة للتجديد لمدد أخرى .
6- تختار لجنة الرقابة الشرعية رئيسًا لها من بين أعضائها ، يمثلها أمام الجمعية العامة للشركة ومجلس إدارتها وكذا أمام الهيئة .
7- تجتمع لجنة الرقابة الشرعية بدعوة من رئيسها ، أو بناء على طلب إثنين من أعضائها على الأقل ، أو بدعوة من رئيس مجلس إدارة الشركة أو العضو المنتدب ، أو الهيئة .
8- يكون اجتماع اللجنة صحيحًا بحضور أغلبية أعضائها ، وتتخذ قراراتها بأغلبية عدد أعضائها وعند التساوي يرجح الجانب الذي منه رئيس الاجتماع ، ولا يجوز الإنابة بين أعضاء اللجنة في حضور اجتماعاتها أو عند التصويت على القرارات .
9- في حال خلو عضوية أحد أعضاء لجنة الرقابة الشرعية ، يقوم مجلس إدارة الشركة باختيار عضو آخر بذات الإجراءات المشار إليها بالبندين (1 ، 2) من هذه المادة ، على أن يعرض العضو الذي وافقت عليه الهيئة على الجمعية العامة للشركة في أول اجتماع لاحق لها للنظر في الموافقة على تعيينه .
10- لا يجوز عزل لجنة الرقابة الشرعية المعينة أو أي عضو منها إلا بقرار من الجمعية العامة العادية للشركة ، بناء على مبررات يعرضها مجلس إدارتها ، مع إخطار الهيئة بذلك .$b7_0$
  FROM laws WHERE law_no = 70 AND law_year = 2026 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2026-05-07', 'active' FROM ins7_0;

WITH ins8_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 8, 0, NULL, $t8_0$المادة الثامنة - اختصاصات لجنة الرقابة الشرعية$t8_0$, $b8_0$على لجنة الرقابة الشرعية بالشركة التأكد من التزام الشركة بأحكام ومبادئ الشريعة الإسلامية ، وتختص اللجنة بما يلي :
1- مراقبة ومراجعة أعمال التأمين وأعمال الاستثمار لتتوافق مع أحكام ومبادئ الشريعة الإسلامية .
2- مراجعة جميع نماذج عقود وشروط التأمين واتفاقيات إعادة التأمين التي تستخدمها شركة التأمين التكافلي لضمان توافقها مع أحكام ومبادئ الشريعة الإسلامية وإصدار الموافقة بشأنها ، مع تقديم التوصيات المناسبة لجعلها تتفق مع هذه الأحكام والمبادئ .
3- مراقبة الفصل التام بين حساب المساهمين وحساب المشتركين .
4- وضع القواعد الشرعية الأساسية لأعمال شركة التأمين التكافلي واعتماد أو رفض أي نشاط تقوم به شركة التأمين التكافلي في حال عدم اتفاق هذا النشاط مع مبادئ الشريعة الإسلامية في كافة معاملاتها .
5- إصدار الفتاوى الشرعية في الموضوعات ذات الصلة بنشاط التأمين التكافلي ، والرد على أي أسئلة أو استفسارات توجهها لها الشركة أو الهيئة والمتعلقة بالمسائل الشرعية ، وتكون الفتاوى الصادرة عن لجنة الرقابة الشرعية ملزمة للشركة ، وفي حال عدم اتفاق الشركة مع رأي اللجنة يتم إخطار الهيئة بالأمر لعرضه على لجنة الرقابة الشرعية المركزية للبت فيه .
6- الاطلاع في أي وقت على جميع سجلات وعقود ومستندات الشركة ، ولها أن تطلب الإيضاحات التي تراها ضرورية لأداء مهمتها ، وعلى إدارة الشركة تقديم تلك الإيضاحات وذلك دون الإخلال بحكم المادة (153) من قانون التأمين الموحد . وفي حال عدم قيام الشركة بتمكين اللجنة من أداء مهمتها ، فعلى اللجنة إثبات ذلك في تقرير ترفعه إلى لجنة المراجعة بالشركة ، مع إخطار الهيئة بذلك .
7- إعداد وتقديم تقرير سنوي إلى الجمعية العامة للشركة تبين فيه خلاصة ما قامت به من أعمال مع ملاحظاتها بشأن معاملات الشركة ومدى التزامها بأحكام ومبادئ الشريعة الإسلامية ، مع الالتزام بتقديم نسخة من التقرير إلى الهيئة ضمن المستندات الواجب تقديمها إليها قبل انعقاد الجمعية العامة لشركة التأمين التكافلي بشهر على الأقل ، ويدرج التقرير ضمن التقرير السنوي للشركة .
8- موافاة الهيئة ولجنة المراجعة الداخلية بالشركة بنسخة من محاضر اجتماعاتها التي تعقدها ، وذلك خلال أسبوعين من تاريخ انعقادها على أن تكون مستوفاة كافة التوصيات والآراء التي أبداها أعضاء اللجنة .$b8_0$
  FROM laws WHERE law_no = 70 AND law_year = 2026 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2026-05-07', 'active' FROM ins8_0;

WITH ins9_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 9, 0, NULL, $t9_0$المادة التاسعة - التزامات شركة التأمين التكافلي$t9_0$, $b9_0$يضع مجلس إدارة شركة التأمين التكافلي لائحة داخلية يحدد فيها علاقة لجنة الرقابة الشرعية بإدارات الشركة وبالمراقب الشرعي ، ويجب موافاة الهيئة بها للحصول على عدم ممانعة بشأنها .
وعلى الشركة تحديد آلية حصول لجنة الرقابة الشرعية على استشارات وخبرات فنية من خارج الشركة لتعزيز قيامها بأعمالها إذا اقتضى الأمر ذلك ، على أن تكون على نفقة الشركة .
وعلى الشركة الإفصاح في التقرير السنوي عما يلي :
1- أسماء ومؤهلات أعضاء لجنة الرقابة الشرعية .
2- عدد اجتماعات لجنة الرقابة الشرعية التي تمت خلال السنة .
3- أي علاقة أو معاملة تمت مع أي عضو من أعضاء لجنة الرقابة الشرعية .$b9_0$
  FROM laws WHERE law_no = 70 AND law_year = 2026 AND kind = 'board_decision'
