WITH ins10_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 10, 0, NULL, $t10_0$المادة العاشرة - اختصاصات المراقب الشرعي$t10_0$, $b10_0$تلتزم شركة التأمين التكافلي بتعيين مراقب شرعي ، يختاره مجلس إدارة الشركة بناءً على توصية لجنة الرقابة الشرعية ، ويجوز أن يكون المراقب الشرعي من بين أعضاء لجنة الرقابة الشرعية بالشركة ، ويقوم المراقب الشرعي ببذل العناية اللازمة لتطبيق قواعد ومعايير التأمين التكافلي بالشركة ، ويختص على وجه الخصوص بما يلي :
1- مراقبة إتباع إدارات الشركة لأحكام التأمين التكافلي في أعمالها ومدى تنفيذها لقرارات وآراء لجنة الرقابة الشرعية بالشركة .
2- إعداد التقارير اللازمة وموافاة لجنة الرقابة الشرعية ومجلس إدارة الشركة بها .
ويجب أن يدعى المراقب الشرعي لحضور اجتماعات لجنة الرقابة الشرعية .$b10_0$
  FROM laws WHERE law_no = 70 AND law_year = 2026 AND kind = 'board_decision'
