WITH ins11_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 11, 0, NULL, $t11_0$المادة الحادية عشرة - الإفصاحات الخاصة بحسابات المشتركين ومساهمي الشركة$t11_0$, $b11_0$تلتزم شركة التأمين التكافلي بفتح حسابات منفصلة لكل من صندوق المساهمين وصندوق المشتركين وبأن يكون استثمارات المشتركين والمساهمين وفقًا لما تجيزه لجنة الرقابة الشرعية وتوافق عليه الهيئة وبمراعاة معايير المحاسبة المصرية . كما تلتزم الشركة بمتطلبات الإفصاح الآتية :
أولاً – إفصاحات عامة :
1- الإفصاح عن السياسات المحاسبية التي تتبعها الشركة .
2- الإفصاح عما تبديه لجنة الرقابة الشرعية بشأن الأعمال التي تقوم بها الشركة إذا كان من شأنها وجود مخالفة لأحكام ومبادئ الشريعة الإسلامية .
3- الإفصاح عن أوجه ومصادر الدخل أو الصرف غير المتفق مع الشريعة الإسلامية ، وطريقة تصرف الشركة في الأموال الناتجة عن هذا الدخل أو الموجودات المترتبة على ذلك الصرف .
4- الإفصاح عن العمليات ذات الأهمية النسبية التي تمت خلال الفترة لأعضاء لجنة الرقابة الشرعية والمراجع الخارجي .
5- الإفصاح عن أسس تحديد وتوزيع الفائض أو سداد العجز .
ثانيًا - السياسات المحاسبية الواجب الإفصاح عنها :
1- الإفصاح عن الأسس التي تتبعها الشركة في حساب العناصر التي تؤثر في حقوق المشتركين .
2- الإفصاح عن الأسس التي تتبعها الشركة في معالجة أي عجز حالي أو متراكم من الفترات السابقة وكيفية معالجته في الفترة المالية الحالية والمستقبلية .
ثالثًا - الإفصاح العام في الإيضاحات المتممة للقوائم المالية :
1- الإفصاح عن إدارة أعمال التأمين .
2- الإفصاح عن الاستثمارات الخاصة بالمشتركين .
3- الإفصاح عن الاستثمارات الخاصة بمساهمي الشركة .
4- الإفصاح عن مقابل إدارة حساب المشتركين .
5- الإفصاح عن الجهة التي تدير استثمارات حقوق المشتركين واستثمارات المساهمين والمقابل الذي تحصل عليه تلك الجهة .
6- الإفصاح عن الأسس التي تتبعها الشركة بالفصل في توزيع العائد عن استثمارات حقوق حملة الوثائق وحقوق المساهمين بالنسبة لكل طرف منهما .
7- الإفصاح عن توزيع الفائض التأميني للمشتركين (على أساس اعتبار جميع أنواع التأمين المختلفة وحدة واحدة) .
8- الإفصاح عن المكاسب والإيرادات التي لم تقرها لجنة الرقابة الشرعية للشركة و مصادر التصرف فيها تفصيلاً .
9- الإفصاح عن الطريقة التي اتبعتها الشركة في توزيع الفائض التأميني مع بيان الأساس الشرعي الذي اتبع في ذلك .
10- الإفصاح عن كيفية التصرف في الفائض التأميني الذي لم يتم توزيعه عند تصفية الشركة .$b11_0$
