WITH ins14_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 14, 0, NULL, $t14_0$المادة الرابعة عشرة - طرق توزيع الفائض التأميني على المشتركين$t14_0$, $b14_0$مع مراعاة أحكام المادة السابقة ، تلتزم الشركة عند توزيع الفائض التأميني على المشتركين بإتباع أي من الطرق الآتية :
1- أن يكون التوزيع على كافة المشتركين كل بحسب نسبة اشتراكه ، ودون النظر لمن حصل على تعويض من عدمه خلال الفترة المالية .
2- أن يكون التوزيع على المشتركين الذين لم يحصلوا على تعويضات خلال الفترة المالية .
3- أن يكون التوزيع على المشتركين بعد خصم التعويضات المدفوعة لهم خلال الفترة المالية .
ويكون توزيع الفائض التأميني على المشتركين بطريقة معامل التوزيع على النحو الآتي :
( أ ) الوصول أولاً إلى وعاء توزيع الفائض التأميني وهو عبارة عن :
الاشتراكات = الاشتراكات + التزامات التغطية التأمينية المتبقية أول المدة - التزامات التغطية التأمينية المتبقية آخر المدة (لكل مشترك) .
التعويضات = التعويضات المسددة + التزامات التغطية المتكبدة آخر المدة - التزامات التغطية المتكبدة أول المدة (لكل مشترك) .
تخصم التعويضات الخاصة بكل مشترك من اشتراكاته وتصل إلى وعاء توزيع الفائض لكل مشترك .
يتم استبعاد وعاء توزيع الفائض سالب القيمة .
يتم جمع أوعية توزيع الفائض للمشتركين والوصول إلى إجمالي وعاء توزيع الفائض .
(ب) معامل التوزيع المشترك = وعاء توزيع الفائض لكل مشترك/إجمالي وعاء توزيع الفائض .
حصة المشترك من الفائض = الفائض القابل للتوزيع × معامل التوزيع المشترك .$b14_0$
  FROM laws WHERE law_no = 70 AND law_year = 2026 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2026-05-07', 'active' FROM ins14_0;

