DO $verify158$
DECLARE
  v_law_id uuid;
  v_n int; v_v int; v_bad int; v_len int;
BEGIN
  SELECT id INTO v_law_id FROM laws WHERE law_no = 70 AND law_year = 2026 AND kind = 'board_decision';
  IF v_law_id IS NULL THEN
    RAISE WARNING '[158] القرار 70/2026 غير موجود — لا تحقق';
    RETURN;
  END IF;
  SELECT count(*), COALESCE(sum(length(body)), 0) INTO v_n, v_len FROM articles WHERE law_id = v_law_id;
  IF v_n <> 23 THEN RAISE EXCEPTION '[158] عدد المواد % بدل 23', v_n; END IF;
  SELECT count(*) INTO v_v FROM article_versions av JOIN articles a ON a.id = av.article_id WHERE a.law_id = v_law_id AND av.version_no = 1 AND av.status = 'active' AND av.effective_from = DATE '2026-05-07';
  IF v_v <> 23 THEN RAISE EXCEPTION '[158] عدد النسخ % بدل 23', v_v; END IF;
  SELECT count(*) INTO v_bad FROM articles WHERE law_id = v_law_id AND (body ~ '[٠-٩۰-۹]' OR body ~ '[ٌ-ْ]' OR body LIKE '%' || chr(65533) || '%' OR body LIKE '%ـ%' OR body LIKE '%صورة إ%' OR body LIKE '%ة ال يع%' OR body LIKE '%ه ال يع%' OR body LIKE '%تد بها%' OR body LIKE '% تروني%' OR body LIKE '%الوقائع المصریة%' OR body LIKE '%الوقائع المصرية –%' OR body LIKE '%وفق ا%' OR body LIKE '%تنفيذ ا%' OR body LIKE '%ثاني ا%' OR body LIKE '%ثالث ا%' OR body LIKE '%مضارب ا%' OR body LIKE '%مع ا %' OR body LIKE '%مقيد ا%' OR body LIKE '%مساهم ا%' OR body LIKE '%طب قا%' OR body LIKE '%ي ستحق%' OR body LIKE '%ي مثل%' OR body LIKE '%ي رجح%' OR body LIKE '%ي عرض%' OR body LIKE '%ي دعى%' OR body LIKE '%ي لغى%' OR body LIKE '%ي عمل%' OR body LIKE '%ت حدد%' OR body LIKE '%الم عترض%' OR body LIKE '%2 ، 1%');
  IF v_bad > 0 THEN RAISE EXCEPTION '[158] % مادة بها تلف أو بقايا OCR أو ترويسة', v_bad; END IF;
